import os

TL = None


def log(msg):
    print(f"[TELE] {msg}")


def log_err(msg):
    log(f"[ERROR] {msg}")


def tl_instance():
    return TL


def tl_register(user):
    global TL
    try:
        if os.path.isfile(f"/home/{user}/NO_IMD"):
            log(f"Telemetry is OFF for user {user}")
            return None
        if TL is None:
            import taf.ul.telemetry
            TL = taf.ul.telemetry.telemetry_register()
        log(f"Registered instance: {TL}")
    except Exception as exc:
        log_err(f"Cannot register: {exc}")
    return TL


def tl_trace(name, attributes):
    try:
        log(f"Trace: {name} {attributes}")
        with TL.trace(name) as trace:
            trace.set_attributes(attributes)
    except Exception as exc:
        log_err(f"Cannot trace: {exc}")


def tl_update(counter_id, counter_value, metadata):
    try:
        log(f"Update: {counter_id} {counter_value} {metadata}")
        TL.update(counter_id, counter_value, metadata)
    except Exception as exc:
        log_err(f"Cannot update: {exc}")
